void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    // Viewport x,y in [-1.05,1.05], z=5
    vec3 uvw = 2.1*vec3((fragCoord-iResolution.xy*0.5)/min(iResolution.x, iResolution.y), 5.0);
    vec3 V = vec3(0.0, 0.0, 1.0); // View direction, "infinite viewer" (orthographic view)

    // Large sphere, radius 1.0
    const float r1 = 1.0;

    // A gradient background
    vec3 bgcolor = (0.5 + 0.5*smoothstep(-1.0, 1.0, uvw.y)) * vec3(0.0, 0.5, 0.2);

    // Adjust scale by mouse drags (down-drag zooms out, up-drag zooms in)
    float zoom = pow(0.98,iMouse.y-abs(iMouse.w));
    uvw.xy = zoom*uvw.xy;

    // This particular demo wants to know our AA step size in object-space coords
    float dP = fwidth(uvw.x); // Our u and v are both in the view plane - either works

    // Outer bounds mask. Adds dP for slightly more margin in distant views.
    float bounds = 1.0 - aastep(r1 + 0.05 + 2.0*dP, length(uvw.xy));
    if(bounds == 0.0) { // Early exit outside object - this can save a ton of work
        fragColor = vec4(bgcolor, 1.0);
        return;
    }

    mat3 M; // M maps view coords to object coords (not the other way around)
    // Rotate up and down
    float el = 0.1*sin(iTime);
    float Se = sin(el);
    float Ce = cos(el);
    M = mat3(1.0, 0.0, 0.0, 0.0, Ce, -Se, 0.0, Se, Ce);
    // Rotate side to side
    float az = 0.5 + 0.6*sin(iTime*sqrt(0.5));
    float Sa = sin(az);
    float Ca = cos(az);
    M = M * mat3(Ca, 0.0, Sa, 0.0, 1.0, 0.0, -Sa, 0.0, Ca);

    // M = mat3(1.0); // Kill the rotations during development

    mat3 Mi = transpose(M); // Orthonormal matrix, transpose = inverse

    V = M * V; // Transform view direction to object space
    vec3 p = M * uvw; // Ray origin for this fragment, in object space

    // Trace the sphere
    vec4 qt1 = tracesphere(p, V, r1+dP);
    vec3 N1 = qt1.xyz*(1.0/(r1+dP)); // (r1 = 1.0, but dP adds a little to it)

    // AA outline. This is somewhat of a hack:
    // shave off about one pixel around the rim of the sphere to
    // avoid having the AA smoothstep() interpolating "into the void",
    // as this would result in sparkly noise. The rendered radius of
    // this sphere is r1, but the traced radus is r1+dP. Hence, the rim
    // has a normal that is not exactly perpendicular to the view direction.
    // The deviation is very small, except for extremely zoomed-out views.
    float spheremask = 1.0 - aastep(r1, length((Mi*qt1.xyz).xy));

    // Raytracing hack: a "beyond-the-rim N" to reduce aliasing around edges
    // (Makes no real difference now, though, with our careful nudges of aastep())
    vec3 N = normalize(vec3(uvw.xy, 0.0));
    N = mix(N, N1, spheremask);
    // Because V and p were in object coords, N1 and N are as well.

    vec3 g;
    float bump = psrdnoise(N1*10.0, vec3(0.0), 0.0, g);
    g = g*10.0; // Inner derivative of N1*10.0

    // AA/LOD: Bump the normal only if we are close enough to resolve the bumps
    float LODblend = smoothstep(1.0/60.0, 1.0/40.0, dP); // If sphere radius < 70 (approx 50*pi/2)
    float specpower = mix(10.0, 5.0, LODblend); // Fudge the Phong specular "roughness" to
    float bumpamount = mix(0.02, 0.0, LODblend); // compensate for lack of bumps in distant views

    // Bump the normal
    vec3 N_ = g - dot(g, N) * N; // N_ orthogonal to N
    vec3 bumpedN = N - bumpamount * bump * N_;
    bumpedN = normalize(bumpedN);

    vec3 L = M * normalize(vec3(1.0, 2.0, 3.0)); // Directional light
    vec3 diffusecolor = vec3(0.0,0.3,0.8);
    vec3 Id = diffusecolor * max(0.0, dot(bumpedN, L));
    vec3 Ia = diffusecolor;
    vec3 mixcolor = mix(Id, Ia, 0.2); // 0.1*Ia + 0.9*Id

    vec3 specularcolor = vec3(1.0);
    vec3 R = reflect(-L, bumpedN);
    float ks = max(0.0, dot(R, V));
    ks = pow(ks, specpower);
    vec3 Is = specularcolor * ks;

    // Fake high intensity for the specular highlight: blend, don't add!
    mixcolor = mix(mixcolor, vec3(1.0), Is*1.0);

    mixcolor = mix(bgcolor, mixcolor, spheremask); // AA outline

    fragColor = vec4(mixcolor, 1.0);
}

